"""The irreducible quotient of a cyclic module (generated by basis vector 0) as matrices."""
import numpy as np
from lalg import N
def quotient(F, M):
    d = M[0].shape[0]
    W = np.eye(d, dtype=np.int64)[1:]
    while len(W):
        Q = F.nullspace(W)
        A = np.vstack([F.dot(Q, F.dot(M[k], W.T)) for k in range(N)])
        C = F.nullspace(A, len(W))
        if len(C) == len(W): break
        W = F.rref(F.dot(C, W))[0] if len(C) else np.zeros((0, d), dtype=np.int64)
    # basis of V/W: complement coordinates = non-pivot columns of rref(W)
    if len(W):
        R, piv = F.rref(W)
    else:
        R, piv = np.zeros((0, d), dtype=np.int64), []
    comp = [c for c in range(d) if c not in piv]
    # reduce x modulo W: x -> x - sum x[piv_i] R_i ; coordinates = entries at comp
    def red(x):
        x = x.copy()
        for i, pc in enumerate(piv):
            if x[pc]: x ^= F.T[x[pc], R[i]]
        return x[comp]
    out = []
    for k in range(N):
        cols = [red(M[k][:, c]) for c in comp]
        out.append(np.array(cols).T)
    return out
